# langs/chicken.py
"""Chicken — язык, где единственное слово — «chicken»."""

from core.base import Language
from langs.brainfuck import run_brainfuck_io as run_brainfuck
from core.translate import TRANSPILERS


CHICKEN_OPCODES = [">", "<", "+", "-", ".", ",", "[", "]"]


def _chicken_to_bf(src):
    bf = []
    for line in src.splitlines():
        line = line.strip().lower()
        if not line:
            continue
        count = line.count("chicken")
        if count > 0:
            bf.append(CHICKEN_OPCODES[(count - 1) % 8])
    return "".join(bf)


def _chicken_print(text):
    """Chicken-программа. Каждый символ: [-] + × n ."""
    parts = []
    for ch in text:
        n = ord(ch) & 0xFF
        parts.append("chicken " * 7 + "\n")     # [ (7)
        parts.append("chicken " * 4 + "\n")     # - (4)
        parts.append("chicken " * 8 + "\n")     # ] (8)
        parts.append(("chicken " * 3 + "\n") * n)  # + × n
        parts.append("chicken " * 5 + "\n")     # . (5)
    return "".join(parts)


def _chicken_to_python(src):
    from langs.brainfuck import _bf_to_python
    return _bf_to_python(_chicken_to_bf(src))


class ChickenLang(Language):
    name = "chicken"
    title = "Chicken"
    category = "Э"
    ext = ".chicken"
    keywords = ["chicken"]
    comment_regex = None

